-- 乌鸦子弹, 羽毛


---@type ParkourGameUtil
local ParkourGameUtil = import("Game.Activity.ParkourGame.ParkourGameUtil")
---@type ParkourGameMgr
local Mgr = import("Game.Activity.ParkourGame.ParkourGameMgr"):GetInstance()

local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
local KTool = CS.Engine.Lib.KTool

---@class BulletFeather:TrackTriggerItem
local BulletFeather = Class("BulletFeather", import("Game.Activity.ParkourGame.MainGame.TrackItems.TrackTriggerItem"))

function BulletFeather:Type()
    return ParkourGameUtil.TrackItemType.BulletFeather
end

--function BulletFeather:Start()
--    self.super.Start(self)
--    self.speed = self.speed or 4
--    self.pos = self.transform.localPosition
--    self.move = 0 --减少对transform的操作
--end

function BulletFeather:Init(pos, speed, parent)
    self.pos = pos
    self.speed = speed
    self.move = 0
    self.transform:SetParent(parent)
    self.transform.localPosition = pos
    CfUtils.SetActive(self.gameObject,true)

    CriWareUtils.PlaySe( "Audio/sfx_instance_miniworld_parkour", "crow_feather_12001801" )
end

function BulletFeather:Tick(deltaTime)
    self.move = self.move - deltaTime * self.speed

    self.transform.localPosition = Vector3(self.pos.x + self.move, self.pos.y, self.pos.z)
    
    if self:CheckOutRange() then
        self:Recycle()
    end
end

function BulletFeather:CheckOutRange()
    return self.pos.x + self.move < -9
end

function BulletFeather:PlayLogic(other)
    local idComp = KTool.GetComponent(other.gameObject, typeof(CS.Game.Native.Common.ID))
    local isRoleHit = isNotNull(idComp) and idComp.stringId == "hitCollider" -- 猫下面一层的碰撞体, 执行 hit 碰撞
    if isRoleHit then 
        return
    end 


    local isPlayer = other.name == Mgr.player.controller.gameObject.name
    if isPlayer then
        local player = Mgr.player
        if player:OnHit(self.Type()) then
            player:SetRoleFX( "fx_role_injured_feather", true )
        end
    end
    self:Recycle()
end



return BulletFeather